const $=id=>document.getElementById(id);let ctx,node,analyser,running=false,latest=null,starting=false,hostBenchmark=null;
fetch('array-benchmark-v05.json').then(r=>r.ok?r.json():null).then(v=>{hostBenchmark=v;}).catch(()=>{});
const ids=['target','masker','head','steer','snr','noise','method','loading','volume','steeringMode','doaChannels','doaSector','trackPolicy'];
function settings(){let c=Object.fromEntries(ids.map(id=>[id,['noise','method','steeringMode','trackPolicy'].includes(id)?$(id).value:+$(id).value]));c.neural=$('neural').checked;return c;}
function draw(){const c=settings();for(let k of ['target','masker','head','steer','volume'])$(k+'-value').textContent=c[k]+(k==='volume'?' dB':'°');for(let k of ['target','masker']){let a=c[k]*Math.PI/180;$(k+'Dot').setAttribute('transform',`translate(${260+125*Math.sin(a)} ${165-125*Math.cos(a)})`);}let a=c.steer*Math.PI/180;$('steerLine').setAttribute('d',`M260 165L${260+110*Math.sin(a)} ${165-110*Math.cos(a)}`);$('headShape').setAttribute('transform',`rotate(${c.head} 260 165)`);$('algo').textContent=(10.6666667+(c.neural?30:0)).toFixed(2);}
function config(relearn=false){draw();node?.port.postMessage({type:'config',value:settings()});if(relearn&&node){node.port.postMessage({type:'calibrate'});$('calibration').textContent='Noise field changed: recalibrating for 1 second with target muted.';}}
for(let id of ids)$(id).addEventListener('input',()=>config(['target','masker','head','snr','noise'].includes(id)));
$('neural').onchange=()=>config();$('lockTarget').onclick=()=>{if(!node)return;if($('steeringMode').value!=='tracked'){$('steeringMode').value='tracked';config();}$('trackPolicy').value='lock';config();node.port.postMessage({type:'lock',angle:+$('steer').value});$('doaEstimate').textContent=`Waiting for a confirmed track within 45° of ${$('steer').value}°…`;};$('point').onclick=()=>{$('steer').value=$('target').value;config();};$('calibrate').onclick=()=>node?.port.postMessage({type:'calibrate'});
async function decode(buf){const a=await ctx.decodeAudioData(buf);let x=new Float32Array(a.length);for(let c=0;c<a.numberOfChannels;c++){const y=a.getChannelData(c);for(let i=0;i<x.length;i++)x[i]+=y[i]/a.numberOfChannels;}let rms=Math.sqrt(x.reduce((s,v)=>s+v*v,0)/x.length),gain=.05/Math.max(rms,1e-8);for(let i=0;i<x.length;i++)x[i]*=gain*Math.min(1,i/240,(x.length-1-i)/240);return x;}
$('play').onclick=async()=>{if(starting)return;starting=true;try{if(!ctx){$('status').textContent='Loading local audio and pretrained RNNoise…';ctx=new AudioContext({sampleRate:48000,latencyHint:'interactive'});await ctx.audioWorklet.addModule('array-processor.js');node=new AudioWorkletNode(ctx,'array-processor',{numberOfInputs:0,numberOfOutputs:1,outputChannelCount:[2]});node.port.onmessage=({data:d})=>{if(d.type==='error'){$('status').textContent='Audio error: '+d.message;}if(d.type==='ready')$('status').textContent='Running · learning the noise field';if(d.type==='stats'){latest=d.value;telemetry();}};for(let i=0;i<2;i++){const r=await fetch('assets/'+(i?'interferer':'speech')+'.wav');if(!r.ok)throw Error('Audio asset load failed');node.port.postMessage({type:'source',index:i,value:await decode(await r.arrayBuffer())});}config();analyser=ctx.createAnalyser();analyser.fftSize=1024;node.connect(analyser).connect(ctx.destination);setInterval(()=>node?.port.postMessage({type:'stats'}),1000);scope();}if(running){await ctx.suspend();running=false;$('play').textContent='Resume experiment';$('status').textContent='Paused';}else{await ctx.resume();running=true;$('play').textContent='Pause';$('status').textContent='Running · four-microphone streaming DSP';}}catch(e){$('status').textContent='Unable to start: '+e.message;await ctx?.close();ctx=null;node=null;running=false;$('play').textContent='Retry experiment';}finally{starting=false;}};
$('upload').onchange=async e=>{if(!ctx){$('status').textContent='Start the experiment before loading a file.';e.target.value='';return;}try{const f=e.target.files[0];if(!f)return;node.port.postMessage({type:'source',index:0,value:await decode(await f.arrayBuffer())});node.port.postMessage({type:'calibrate'});}catch(e){$('status').textContent='Could not decode audio: '+e.message;}};
const delay={'scene renderer':'0.24–0.77 ms propagation','analysis FFT ×4':'10.67 ms STFT total¹','localization SRP-PHAT':'0 ms audio queue; 100 ms smoothing','tracking (TF voting + tracker)':'0 ms queue; 150 ms histogram','noise covariance (calibration)':'0 ms; 1 s learning','weight solve (on change)':'0 ms added queue','spatial filtering':'0 ms added queue','synthesis IFFT ×2':'included in STFT¹','RNNoise ×2 (including framing)':'30 ms²','level + digital ceiling':'0 ms','total audio block':'see total above'};
function telemetry(){let v=latest;if(!v)return;const loc=v.localization;if(loc){const a=loc.direction_head_deg==null?null:((loc.direction_head_deg+(+($('head').value))+540)%360)-180;$('doaEstimate').textContent=a===null?'DOA: waiting for active audio':`Estimated direction ${a.toFixed(0)}° world · applied steering ${loc.applied_direction_world_deg.toFixed(0)}°`;$('doaDetail').textContent=`${loc.channels} microphones; peak contrast ${loc.peak_contrast.toFixed(3)} (not probability); update every ${loc.update_interval_ms.toFixed(1)} ms; 100 ms exponential smoothing. ${loc.valid?'Active estimate':'Inactive/uncertain; holding direction'}. Full-circle two-microphone localization has front/back ambiguity.`;const tr=loc.tracking,dots=$('trackDots');dots.replaceChildren();if(tr){const ns='http://www.w3.org/2000/svg';for(const t of tr.tracks){const w=(t.angle_deg+tr.head_deg)*Math.PI/180,c=document.createElementNS(ns,'circle');c.setAttribute('cx',260+140*Math.sin(w));c.setAttribute('cy',165-140*Math.cos(w));c.setAttribute('r',t.id===tr.target_id?9:6);c.setAttribute('fill',t.id===tr.target_id?'#b6c9fa':'none');c.setAttribute('stroke','#b6c9fa');c.setAttribute('stroke-width','2');c.setAttribute('opacity',t.coasting?'.45':'1');dots.append(c);}const sel=tr.target_deg==null?null:((tr.target_deg+tr.head_deg+540)%360)-180;$('doaEstimate').textContent=sel==null?(tr.awaiting_lock_deg!=null?'Waiting for a confirmed track near the designated direction…':'Tracking: no speech-like source selected yet'):`Tracked target ${sel.toFixed(0)}° world · ${tr.tracks.length} source${tr.tracks.length===1?'':'s'} tracked${tr.crossing_hold?' · crossing: holding prediction':''}`;$('doaDetail').textContent=`Policy: ${tr.policy==='lock'?'lock-on (identity by direction continuity, not by voice)':'speech-like (highest amplitude modulation)'}. `+tr.tracks.map(t=>`#${t.id} ${((t.angle_deg+tr.head_deg+540)%360-180).toFixed(0)}° mod ${t.modulation.toFixed(2)}${t.coasting?' (coasting)':''}`).join(' · ');}
 if(a!==null){$('doaDot').setAttribute('visibility','visible');$('doaDot').setAttribute('transform',`translate(${260+95*Math.sin(a*Math.PI/180)} ${165-95*Math.cos(a*Math.PI/180)})`);}}const host=hostBenchmark?.runs.find(r=>r.method===$('method').value&&r.neural===$('neural').checked&&r.steeringMode===$('steeringMode').value),live=Object.keys(v.timings).length>0,measurements=live?v.timings:host?.timings??{};$('timingSource').textContent=live?'Timing source: this browser AudioWorklet':'Timing source: separate Node host benchmark — '+(hostBenchmark?.cpu??'loading')+'; NOT live browser compute. Host uses four localization microphones and full-circle search; your geometry may differ. Memory below is live.';if(running)$('status').textContent=v.calibration_remaining_ms>0?'Running · learning noise (target muted)':'Running · noise covariance frozen';$('rtf').textContent=v.rtf==null?'Unavailable':v.rtf.toFixed(3);$('calibration').textContent=v.calibration_remaining_ms>0?`Learning noise: ${v.calibration_remaining_ms.toFixed(0)} ms left · target muted`:`Noise covariance frozen from ${v.noise_frames} frames · ${v.fallback_bins} bins fell back to delay-and-sum`;$('io').textContent=`AudioContext: ${ctx.sampleRate} Hz; baseLatency ${(1000*ctx.baseLatency).toFixed(2)} ms; outputLatency ${ctx.outputLatency===undefined?'unavailable':(1000*ctx.outputLatency).toFixed(2)+' ms'}. These browser estimates are shown separately; no acoustic end-to-end measurement.`;$('timings').innerHTML=Object.entries(delay).map(([k,d])=>{const s=measurements[k]??(!live?host?.calibration_timings[k]:null);return `<tr><td>${k}</td><td>${d}</td>${['p50_ms','p95_ms','p99_ms','max_ms'].map(p=>`<td>${s?s[p].toFixed(3):'—'}</td>`).join('')}</tr>`;}).join('');$('timingNote').innerHTML=`${Object.keys(v.timings).length?'Live clock available':'AudioWorklet clock unavailable. TABLE SHOWS NODE HOST BENCHMARK, NOT LIVE BROWSER COMPUTE: '+(hostBenchmark?.cpu??'loading…')}. Statistics cover the latest up to 2048 calls per component, including prior settings; export records the current configuration, not a controlled experiment. ${live?`${v.overruns} live block-budget overruns / ${v.timed_blocks} timed blocks`:`Host benchmark: ${host?.overruns??'—'} overruns / ${host?.timed_blocks??'—'} blocks; live deadline measurements unavailable` }. Timers exclude telemetry serialization. ¹ Analysis/synthesis share one 512-sample delay; do not add twice. ² 10 ms adapter queue + 20 ms bundled RNNoise delay; verified by speech correlation. <a href="array-benchmark-v05.json">Node report</a>.`;
const meaning={localization_numeric_bytes:'SRP templates, cross spectra and score grid',tracking_numeric_bytes:'Per-bin cross spectra and direction histogram (templates shared)',scene_state_bytes:'Source delay lines',source_PCM_bytes:'Decoded source audio',beamformer_numeric_bytes:'FFT, covariance, weights and signal buffers',io_numeric_bytes:'128-sample channel buffers',neural_adapter_bytes:'Two 480-sample input/output pairs',wasm_heap_reserved_bytes:'WASM linear memory, shared by two states',profiling_numeric_bytes:'Timing sample rings'};$('memory').innerHTML=Object.entries(v.memory).map(([k,b])=>`<tr><td>${k.replaceAll('_',' ')}</td><td>${b.toLocaleString()}</td><td>${meaning[k]}</td></tr>`).join('');}
function scope(){const canvas=$('spectrum'),g=canvas.getContext('2d'),data=new Uint8Array(analyser.frequencyBinCount);function frame(){if(running){analyser.getByteFrequencyData(data);g.clearRect(0,0,canvas.width,canvas.height);g.strokeStyle='#a1dec7';g.beginPath();for(let i=0;i<256;i++){let x=i/255*canvas.width,y=canvas.height-data[i]/255*canvas.height;i?g.lineTo(x,y):g.moveTo(x,y);}g.stroke();}requestAnimationFrame(frame);}frame();}
$('export').onclick=()=>{const blob=new Blob([JSON.stringify({version:'0.5',utc:new Date().toISOString(),settings:settings(),telemetry:latest,scope:'Synthetic free-field; manual or SRP-estimated direction; telemetry may span settings'},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='array-experiment.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};const baseline=new URLSearchParams(location.search).get('baseline');if(['das','mvdr'].includes(baseline))$('method').value=baseline;if(baseline==='rnnoise')$('neural').checked=true;draw();
